            state = 'A'
            z = 0
        else:
            x = sig['x']
            if state == 'A':
                state = 'B' if x else 'A'
            elif state == 'B':
                state = 'C' if x else 'B'
            else:  # state == 'C'
                state = 'C' if x else 'B'
