        if not cur_areset:
            if state == 0:
                if cur_x:
                    state = 1
            elif state == 1:
                if cur_x:
                    state = 2
            else:  # state == 2
                if cur_x:
                    state = 2
                else:
                    state = 1

        # Moore output after settled posedge: B -> 1, A/C -> 0.
        if state == 1:
            z = 1
        else:
            z = 0
        out.append({"z": z})

        # mid changes occur after sampling and are carried to the start of the next row.
        if "mid" in row:
            mid = row["mid"]
            if mid:
                try:
                    items = mid.items()
                    for k, v in items:
                        if k == "areset":
                            cur_areset = v
                            # async_reset: mid-cycle assertion resets state immediately.
                            if cur_areset:
                                state = 0
                        elif k == "x":
                            cur_x = v
